#!/usr/bin/env python3
import hashlib,json,re,subprocess,sys
from pathlib import Path
d=Path(__file__).resolve().parents[2];p=d/'research/nine-sharing-sign33-forward-norm-w-check';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest()
for n,h in {'run.py':'8b45ba33abaf77c7cd4436ebb7df4db32ce03a589d0b827704c011799f1c1d41','provider_survey.py':'e93e0ae60790a3d94e7fa5dcc43319e962df44972ad865e7989b00f738809f25','source-manifest.json':'f754eb4ec90b5edd2f65da5c335765ac78ff7f7d59d200218db47692eab1b764'}.items():assert sha(p/n)==h
rows=json.loads((p/'source-manifest.json').read_text())['rows'];expected=[('Sign33ForwardNormW38','2f02849769889d60315257413057b3d937cb2a52d1d6b3b8c272bf40566cea93',['Norm38ReferenceTerminals','Norm38ReferenceFieldsAll','Norm38ForwardGatesAssembly','Norm38ForwardPrefix'],'w_terminal'),('Sign33ForwardNormW','6d6cd44527c31d301c2859cf85680045663798a2412b8d284fb3b68d46f66a01',['Sign33ForwardNormW38','SharingForward33','Sign33ResidualAssembly'],'norm_w_of_core')];assert len(rows)==2
for row,(n,h,imports,t) in zip(rows,expected):
 s=(p/'src/DiophantineConsistency'/f'{n}.lean').read_text();assert row['module']=='DiophantineConsistency.'+n and sha(p/'src/DiophantineConsistency'/f'{n}.lean')==row['source_sha256']==h and re.findall(r'^import ([\w.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.'+x for x in imports];assert re.findall(r'^theorem (\w+)',s,re.M)==[t] and s.count('#print axioms ')==1
a=(p/'src/DiophantineConsistency/Sign33ForwardNormW38.lean').read_text();b=(p/'src/DiophantineConsistency/Sign33ForwardNormW.lean').read_text()
for x in ['d.W = 1','forward_gatesHold ι ports u','static_terminals_agree','forward_prefix','reference_terminal_fields_combined','ht.2.2.2.1.trans (hc.2.2.2.1.trans hw)','witnessCoordinates ports u) 66']:assert x in a
for x in ['d.W = 1','Sign33ForwardNormW38.w_terminal ports u hw','Fin.cons (1 : V)','Sign33ResidualBatch05.q ports v','Sign33ResidualBatch05.t ports v','ι (ports 1)','ι (v 9)+1','ι (v 2)+1','ι (v 3)+1','ι (v 4)+1','convert ht using 1']:assert x in b
fields=(d/'research/nine-sharing-norm38-reference-fields-combine-check/src/DiophantineConsistency/Norm38ReferenceFieldsAll.lean').read_text();term=(d/'research/nine-sharing-norm38-reference-terminals-check/src/DiophantineConsistency/Norm38ReferenceTerminals.lean').read_text();assert 'reference p x 78 = d.U ∧ reference p x 66 = d.W' in fields and 'pairValue ι (v 78)=ref 78 ∧ pairValue ι (v 66)=ref 66' in term
nodes=(d/'research/nine-sharing-norm38-model-bridge-draft/NormAssignment38.lean').read_text()
for x in ['let a21 : SignedPair S := pairCompute GateOp.mul a14 a0','let a22 : SignedPair S := pairCompute GateOp.add a21 a18','let a45 : SignedPair S := pairCompute GateOp.sub a22 a1','let a46 : SignedPair S := pairCompute GateOp.sub a45 a2','let a62 : SignedPair S := pairCompute GateOp.add a15 a8','let a63 : SignedPair S := pairCompute GateOp.mul a62 a46','let a64 : SignedPair S := pairCompute GateOp.add a63 a45','let a65 : SignedPair S := pairCompute GateOp.mul a3 a21','let a66 : SignedPair S := pairCompute GateOp.sub a64 a65']:assert x in nodes
batch=(d/'research/nine-sharing-sign33-residual-batch05-check/src/DiophantineConsistency/Sign33ResidualBatch05.lean').read_text();assert 'def q (ports' in batch and 'q ports v)+q ports v)-' in batch and '((ι (v 4)+1)*t ports v)))-1' in batch
r=subprocess.run([sys.executable,'-I','-S','-B',str(p/'run.py'),'--preflight'],capture_output=True,text=True,check=True,timeout=300);o=json.loads(r.stdout);assert not r.stderr and o['status']=='PASS_NO_LEAN_PREFLIGHT' and o['stage_count']==2
print(json.dumps({'status':'PASS','preflight':o,'scope':'conditional W-core to 33 constructor expression; no Lean replay'},indent=2,sort_keys=True))
